// مجال أدوات شريط المشغّل وخط الترجمة على الطبقة (تملكه P6). الرسائل التي تظهر للمستخدم في القوائم والرسائل
// العابرة تقول ما حدث وما يمكن فعله (R35)، ونصوصها من مواصفة التصميم الأولى §١٦.٣ حيث وُجدت. ورموز الخط والشريط
// تبقى في التشخيص وحده، فلا رسالة فوق الفيديو بسببها.

export const PREFIXES = Object.freeze(['CT_']);

// الأمثلة الموقّعة داخل جملة عربية معزولة LTR (LRI…PDI)، والناقص الطباعي كما تعرضه الشارة: بلا عزل تأخذ العلامة بعد حرف عربي
// اتجاه السياق فتُرسم «0.5-» و«600-» (تدقيق Fable، FA-05؛ ومثله مثال الزمن في import.js، U41).
const LTR = (s) => `${String.fromCodePoint(0x2066)}${s}${String.fromCodePoint(0x2069)}`;

